.wsearcalm__pog strong{color:#1c1c1c}.wsearcalm__st,.wsearcalm__kv li::before{background:#6d388b}.wsearcalm__tab th{background:#6d388b!important}
.wsearcalm__ti{background:linear-gradient(135deg,#6d388b,#9a6bb5);box-shadow:0 6px 14px rgba(109,56,139,.30)}.wsearcalm__tk{border-color:rgba(109,56,139,.30)}
