div.wsearcalm__pog{text-align:center;border:1px solid rgba(109,56,139,.35);border-radius:16px;transition:transform .2s,box-shadow .2s}div.wsearcalm__pog:hover{transform:translateY(-3px);box-shadow:0 14px 30px rgba(109,56,139,.22)}div.wsearcalm__pog>strong,div.wsearcalm__pog>span:not(.wsearcalm__pi){display:block}
